def apply_safety_thresholds(moderation_result: dict, thresholds: dict) -> dict:
    """
    Applies category thresholds to decide whether to allow text.

    Args:
        moderation_result (dict): The result from a moderation service, e.g., from moderate_text.py.
                                  Expected format: {"category_name": {"severity": int}}
        thresholds (dict): A dictionary of thresholds for each category.
                           Expected format: {"category_name": {"max_severity": int}}

    Returns:
        dict: A dictionary indicating whether the text is allowed and reasons if not.
              Format: {"is_allowed": bool, "reasons": list[str]}
    """
    is_allowed = True
    reasons = []

    for category, result in moderation_result.items():
        if category in thresholds:
            max_severity = thresholds[category]["max_severity"]
            if result["severity"] >= max_severity:
                is_allowed = False
                reasons.append(f"Category '{category}' exceeded max severity threshold (severity: {result["severity"]}, threshold: {max_severity}).")

    return {"is_allowed": is_allowed, "reasons": reasons}

import os
import boto3
from azure.core.credentials import AzureKeyCredential
from azure.ai.contentsafety import ContentSafetyClient

class SafetyClients:
    """
    Provides configured clients for various content safety services.
    """
    _azure_content_safety_client = None
    _aws_comprehend_client = None

    @classmethod
    def get_azure_content_safety_client(cls) -> ContentSafetyClient:
        if cls._azure_content_safety_client is None:
            endpoint = os.environ.get("AZURE_CONTENT_SAFETY_ENDPOINT")
            key = os.environ.get("AZURE_CONTENT_SAFETY_KEY")
            if not endpoint or not key:
                raise ValueError("AZURE_CONTENT_SAFETY_ENDPOINT and AZURE_CONTENT_SAFETY_KEY must be set in environment variables for Azure Content Safety.")
            cls._azure_content_safety_client = ContentSafetyClient(endpoint, AzureKeyCredential(key))
        return cls._azure_content_safety_client

    @classmethod
    def get_aws_comprehend_client(cls):
        if cls._aws_comprehend_client is None:
            region_name = os.environ.get("AWS_REGION", "us-east-1")
            cls._aws_comprehend_client = boto3.client("comprehend", region_name=region_name)
        return cls._aws_comprehend_client
